text:
{{
  (function() {
    const val = Get_Devis_Detail.data[0]?.STATUT || "Brouillon";
    const statut = val.toUpperCase().trim();
    let emoji = "";

    switch (statut) {
      case 'BROUILLON': emoji = '📝 '; break;
      case 'SYNC DEMANDÉE': emoji = '🔄 '; break;
      case 'VALIDÉ': emoji = '✅ '; break;
      case 'ENVOI N8N EN COURS': emoji = '⏳ '; break;
      case 'PDF PRÊT': emoji = '📄 '; break;
      case 'ENVOYÉ': emoji = '📤 '; break;
      case 'ATTENTE CLIENT': emoji = '⏳ '; break;
      case 'TRANSFORMATION DEMANDÉE': emoji = '⚙️ '; break;
      case 'ACCEPTÉ / TRANSFORMÉ': emoji = '🤝 '; break;
      case 'ARCHIVÉ': emoji = '🗄️ '; break;
      default: emoji = '❓ ';
    }

    return emoji + val;
  })()
}}

textColor:
{{
  (() => {
    const statut = (Get_Devis_Detail.data[0]?.Statut || "").toUpperCase().trim();
    switch (statut) {
      case 'PIECE A COMMANDER':
      case 'PIÈCE À COMMANDER': return '#dc2626'; // Rouge
      case 'PIECE EN COMMANDE':
      case 'PIÈCE EN COMMANDE': return '#16a34a'; // Vert
      case 'DEVIS': return '#9333ea'; // Violet
      case 'A REMONTER':
      case 'À REMONTER': return '#ea580c'; // Orange / Rouge
      case 'À DIAGNOSTIQUER': return '#2563eb'; // Bleu
      case 'PRÊT': return '#15803d'; // Vert foncé
      default: return '#0f172a'; // Couleur texte sombre par défaut
    }
  })()
}}
